CREATE TABLE IF NOT EXISTS "accounts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity and the address every billing receipt goes to. One per account, not per profile.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Argon2id hash.
	"password_hash" VARCHAR(255) NOT NULL,
	-- ISO 3166-1 alpha-2 billing country. This, not the request IP, decides which availability windows apply and what the account is charged in.
	"country_code" CHAR(2) NOT NULL,
	-- ISO 4217 currency for all charges on the account.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Concurrent streams allowed by the current plan. Enforced at play time against active sessions.
	"max_streams" SMALLINT NOT NULL DEFAULT 2,
	-- active | on_hold | cancelled. On hold keeps profiles and watch history alive through a payment failure.
	"status" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "accounts" IS 'The billing entity and the thing you sign in to. Everything about money, plan limits and territory hangs here; nothing about taste does.';
COMMENT ON COLUMN "accounts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "accounts"."email" IS 'Login identity and the address every billing receipt goes to. One per account, not per profile.';
COMMENT ON COLUMN "accounts"."password_hash" IS 'Argon2id hash.';
COMMENT ON COLUMN "accounts"."country_code" IS 'ISO 3166-1 alpha-2 billing country. This, not the request IP, decides which availability windows apply and what the account is charged in.';
COMMENT ON COLUMN "accounts"."currency_code" IS 'ISO 4217 currency for all charges on the account.';
COMMENT ON COLUMN "accounts"."max_streams" IS 'Concurrent streams allowed by the current plan. Enforced at play time against active sessions.';
COMMENT ON COLUMN "accounts"."status" IS 'active | on_hold | cancelled. On hold keeps profiles and watch history alive through a payment failure.';
COMMENT ON COLUMN "accounts"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account being billed.
	"account_id" BIGINT NOT NULL,
	-- basic | standard | premium | standard_with_ads. The plan is a code rather than a foreign key so historical rows survive a plan being retired.
	"plan_code" VARCHAR(40) NOT NULL,
	-- trialing | active | past_due | cancelled. Only one row per account is non-terminal at a time.
	"status" VARCHAR(24) NOT NULL,
	-- Recurring charge in minor units. Integer money; never float.
	"price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency of price_cents.
	"currency_code" CHAR(3) NOT NULL,
	-- When this subscription period began.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Next renewal instant. Access is granted up to this point even after a cancellation.
	"current_period_end" TIMESTAMPTZ NOT NULL,
	-- When cancellation was requested. Kept rather than deleting, so win-back campaigns and churn reporting have the date.
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscriptions" IS 'One row per subscription period, appended on plan change rather than updated in place, so a price increase does not rewrite what the customer was charged last year.';
COMMENT ON COLUMN "subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscriptions"."account_id" IS 'Account being billed.';
COMMENT ON COLUMN "subscriptions"."plan_code" IS 'basic | standard | premium | standard_with_ads. The plan is a code rather than a foreign key so historical rows survive a plan being retired.';
COMMENT ON COLUMN "subscriptions"."status" IS 'trialing | active | past_due | cancelled. Only one row per account is non-terminal at a time.';
COMMENT ON COLUMN "subscriptions"."price_cents" IS 'Recurring charge in minor units. Integer money; never float.';
COMMENT ON COLUMN "subscriptions"."currency_code" IS 'ISO 4217 currency of price_cents.';
COMMENT ON COLUMN "subscriptions"."started_at" IS 'When this subscription period began.';
COMMENT ON COLUMN "subscriptions"."current_period_end" IS 'Next renewal instant. Access is granted up to this point even after a cancellation.';
COMMENT ON COLUMN "subscriptions"."cancelled_at" IS 'When cancellation was requested. Kept rather than deleting, so win-back campaigns and churn reporting have the date.';

CREATE INDEX "idx_subscriptions_account_status"
ON "subscriptions" ("account_id", "status");

CREATE TABLE IF NOT EXISTS "profiles" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning account. Profiles are never shared between accounts.
	"account_id" BIGINT NOT NULL,
	-- Name shown on the who-is-watching screen.
	"name" VARCHAR(60) NOT NULL,
	-- Object key of the avatar image. Null falls back to a generated one.
	"avatar_key" VARCHAR(120),
	-- Kids profile: a different home page, no ratings above the maturity ceiling, and no access to account settings.
	"is_kids" BOOLEAN NOT NULL DEFAULT false,
	-- kids | older_kids | teen | adult. Highest rating this profile may be shown.
	"maturity_ceiling" VARCHAR(16) NOT NULL DEFAULT 'adult',
	-- BCP 47 UI and default-audio language. Per profile, because one household is often bilingual.
	"language_code" VARCHAR(8) NOT NULL DEFAULT 'en',
	-- Whether the next episode starts automatically at the credits.
	"autoplay_next" BOOLEAN NOT NULL DEFAULT true,
	-- Optional profile lock. Null when the profile is unlocked.
	"pin_hash" VARCHAR(255),
	-- Profile creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "profiles" IS 'The unit of taste. Every watch row, rating and list entry keys on a profile, not an account - which is the single decision that keeps one housemate out of another one is recommendations.';
COMMENT ON COLUMN "profiles"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "profiles"."account_id" IS 'Owning account. Profiles are never shared between accounts.';
COMMENT ON COLUMN "profiles"."name" IS 'Name shown on the who-is-watching screen.';
COMMENT ON COLUMN "profiles"."avatar_key" IS 'Object key of the avatar image. Null falls back to a generated one.';
COMMENT ON COLUMN "profiles"."is_kids" IS 'Kids profile: a different home page, no ratings above the maturity ceiling, and no access to account settings.';
COMMENT ON COLUMN "profiles"."maturity_ceiling" IS 'kids | older_kids | teen | adult. Highest rating this profile may be shown.';
COMMENT ON COLUMN "profiles"."language_code" IS 'BCP 47 UI and default-audio language. Per profile, because one household is often bilingual.';
COMMENT ON COLUMN "profiles"."autoplay_next" IS 'Whether the next episode starts automatically at the credits.';
COMMENT ON COLUMN "profiles"."pin_hash" IS 'Optional profile lock. Null when the profile is unlocked.';
COMMENT ON COLUMN "profiles"."created_at" IS 'Profile creation time.';

CREATE UNIQUE INDEX "uq_profiles_account_name"
ON "profiles" ("account_id", "name");

CREATE TABLE IF NOT EXISTS "titles" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- film | series. One table for both, because search, artwork, My List, ratings and licensing treat them identically.
	"kind" VARCHAR(16) NOT NULL,
	-- Title as displayed.
	"name" VARCHAR(300) NOT NULL,
	-- Long-form description shown on the detail page.
	"synopsis" TEXT,
	-- Year of first release. A year, not a date - catalog metadata rarely agrees on the day.
	"release_year" SMALLINT NOT NULL,
	-- kids | older_kids | teen | adult, normalised from the local board rating. Compared against profiles.maturity_ceiling.
	"maturity_rating" VARCHAR(16) NOT NULL,
	-- Runtime for a film. Null for a series, whose runtime lives on each episode.
	"runtime_minutes" INTEGER,
	-- BCP 47 language of the original audio, used to decide when to default to dubbed audio.
	"original_language" VARCHAR(8) NOT NULL DEFAULT 'en',
	-- Commissioned in-house. Originals are licensed everywhere and never expire, which is why the badge matters operationally, not just in marketing.
	"is_original" BOOLEAN NOT NULL DEFAULT false,
	-- When the title entered the catalog; drives the "New on" rows.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "titles" IS 'A film or a series as one entity. Collapsing the two costs one nullable runtime column and saves a duplicated set of tables for lists, ratings, licensing and search.';
COMMENT ON COLUMN "titles"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "titles"."kind" IS 'film | series. One table for both, because search, artwork, My List, ratings and licensing treat them identically.';
COMMENT ON COLUMN "titles"."name" IS 'Title as displayed.';
COMMENT ON COLUMN "titles"."synopsis" IS 'Long-form description shown on the detail page.';
COMMENT ON COLUMN "titles"."release_year" IS 'Year of first release. A year, not a date - catalog metadata rarely agrees on the day.';
COMMENT ON COLUMN "titles"."maturity_rating" IS 'kids | older_kids | teen | adult, normalised from the local board rating. Compared against profiles.maturity_ceiling.';
COMMENT ON COLUMN "titles"."runtime_minutes" IS 'Runtime for a film. Null for a series, whose runtime lives on each episode.';
COMMENT ON COLUMN "titles"."original_language" IS 'BCP 47 language of the original audio, used to decide when to default to dubbed audio.';
COMMENT ON COLUMN "titles"."is_original" IS 'Commissioned in-house. Originals are licensed everywhere and never expire, which is why the badge matters operationally, not just in marketing.';
COMMENT ON COLUMN "titles"."added_at" IS 'When the title entered the catalog; drives the "New on" rows.';

CREATE INDEX "idx_titles_kind_year"
ON "titles" ("kind", "release_year");
CREATE INDEX "idx_titles_name"
ON "titles" ("name");

CREATE TABLE IF NOT EXISTS "seasons" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent series. A film never has a row here.
	"title_id" BIGINT NOT NULL,
	-- Ordinal within the series. Specials are usually season 0.
	"season_number" SMALLINT NOT NULL,
	-- Season name where the show uses one, e.g. "Part 2" or a subtitle. Null falls back to "Season N".
	"name" VARCHAR(200),
	-- Year the season first aired.
	"release_year" SMALLINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "seasons" IS 'A season of a series. It exists as its own table rather than a column on episodes so a season can carry its own artwork, name and release year.';
COMMENT ON COLUMN "seasons"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "seasons"."title_id" IS 'Parent series. A film never has a row here.';
COMMENT ON COLUMN "seasons"."season_number" IS 'Ordinal within the series. Specials are usually season 0.';
COMMENT ON COLUMN "seasons"."name" IS 'Season name where the show uses one, e.g. "Part 2" or a subtitle. Null falls back to "Season N".';
COMMENT ON COLUMN "seasons"."release_year" IS 'Year the season first aired.';

CREATE UNIQUE INDEX "uq_seasons_title_number"
ON "seasons" ("title_id", "season_number");

CREATE TABLE IF NOT EXISTS "episodes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent season.
	"season_id" BIGINT NOT NULL,
	-- Ordinal within the season, and the playback order autoplay follows.
	"episode_number" SMALLINT NOT NULL,
	-- Episode title.
	"name" VARCHAR(300) NOT NULL,
	-- Episode description.
	"synopsis" TEXT,
	-- Runtime in seconds. Seconds, not minutes, because resume points and the credits marker are compared against it.
	"runtime_seconds" INTEGER NOT NULL,
	-- Offset where end credits begin, which is when the next-episode prompt appears. Null when nobody has marked it.
	"credits_start_seconds" INTEGER,
	-- Original broadcast or release date, kept for catalog matching against external metadata.
	"air_date" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "episodes" IS 'A playable unit of a series. Films have no rows here - the title itself is the playable - which is the one asymmetry the single titles table costs.';
COMMENT ON COLUMN "episodes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "episodes"."season_id" IS 'Parent season.';
COMMENT ON COLUMN "episodes"."episode_number" IS 'Ordinal within the season, and the playback order autoplay follows.';
COMMENT ON COLUMN "episodes"."name" IS 'Episode title.';
COMMENT ON COLUMN "episodes"."synopsis" IS 'Episode description.';
COMMENT ON COLUMN "episodes"."runtime_seconds" IS 'Runtime in seconds. Seconds, not minutes, because resume points and the credits marker are compared against it.';
COMMENT ON COLUMN "episodes"."credits_start_seconds" IS 'Offset where end credits begin, which is when the next-episode prompt appears. Null when nobody has marked it.';
COMMENT ON COLUMN "episodes"."air_date" IS 'Original broadcast or release date, kept for catalog matching against external metadata.';

CREATE UNIQUE INDEX "uq_episodes_season_number"
ON "episodes" ("season_id", "episode_number");

CREATE TABLE IF NOT EXISTS "media_tracks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Title the track belongs to. Always set, so a dub can be located without joining through seasons.
	"title_id" BIGINT NOT NULL,
	-- Episode the track belongs to. Null for a film, where the title is the playable.
	"episode_id" BIGINT,
	-- audio | subtitle. One table, because the player offers them from the same menu and the licensing is per language either way.
	"kind" VARCHAR(16) NOT NULL,
	-- BCP 47 language of the track.
	"language_code" VARCHAR(8) NOT NULL,
	-- Forced narrative subtitles: shown automatically for foreign dialogue even when subtitles are off.
	"is_forced" BOOLEAN NOT NULL DEFAULT false,
	-- Subtitles for the deaf and hard of hearing, which include sound cues. A distinct track from plain same-language subtitles.
	"is_sdh" BOOLEAN NOT NULL DEFAULT false,
	-- Codec or format, e.g. eac3, atmos, webvtt. Null when the track is still being encoded.
	"codec" VARCHAR(24),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "media_tracks" IS 'Audio and subtitle tracks for a playable. Every stream has several; which ones exist varies per territory, which is why they are rows rather than a language array on the title.';
COMMENT ON COLUMN "media_tracks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "media_tracks"."title_id" IS 'Title the track belongs to. Always set, so a dub can be located without joining through seasons.';
COMMENT ON COLUMN "media_tracks"."episode_id" IS 'Episode the track belongs to. Null for a film, where the title is the playable.';
COMMENT ON COLUMN "media_tracks"."kind" IS 'audio | subtitle. One table, because the player offers them from the same menu and the licensing is per language either way.';
COMMENT ON COLUMN "media_tracks"."language_code" IS 'BCP 47 language of the track.';
COMMENT ON COLUMN "media_tracks"."is_forced" IS 'Forced narrative subtitles: shown automatically for foreign dialogue even when subtitles are off.';
COMMENT ON COLUMN "media_tracks"."is_sdh" IS 'Subtitles for the deaf and hard of hearing, which include sound cues. A distinct track from plain same-language subtitles.';
COMMENT ON COLUMN "media_tracks"."codec" IS 'Codec or format, e.g. eac3, atmos, webvtt. Null when the track is still being encoded.';

CREATE INDEX "idx_media_tracks_lookup"
ON "media_tracks" ("title_id", "episode_id", "kind", "language_code");

CREATE TABLE IF NOT EXISTS "availability_windows" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Licensed title.
	"title_id" BIGINT NOT NULL,
	-- ISO 3166-1 alpha-2 territory the licence covers. One row per country, because a deal almost never covers the same dates everywhere.
	"country_code" CHAR(2) NOT NULL,
	-- Instant the title becomes playable in that territory. Future rows drive the "coming soon" rail.
	"starts_at" TIMESTAMPTZ NOT NULL,
	-- Instant the licence lapses. Null means perpetual, which in practice means an original.
	"ends_at" TIMESTAMPTZ,
	-- Whether the licence is exclusive in that territory; drives the badge and affects renewal negotiation.
	"is_exclusive" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "availability_windows" IS 'Time-boxed licensing, one row per title per territory. Catalog queries are always filtered by country and now() against this table, which is why a title silently vanishing at month end is a data fact rather than a bug.';
COMMENT ON COLUMN "availability_windows"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "availability_windows"."title_id" IS 'Licensed title.';
COMMENT ON COLUMN "availability_windows"."country_code" IS 'ISO 3166-1 alpha-2 territory the licence covers. One row per country, because a deal almost never covers the same dates everywhere.';
COMMENT ON COLUMN "availability_windows"."starts_at" IS 'Instant the title becomes playable in that territory. Future rows drive the "coming soon" rail.';
COMMENT ON COLUMN "availability_windows"."ends_at" IS 'Instant the licence lapses. Null means perpetual, which in practice means an original.';
COMMENT ON COLUMN "availability_windows"."is_exclusive" IS 'Whether the licence is exclusive in that territory; drives the badge and affects renewal negotiation.';

CREATE INDEX "idx_windows_country_range"
ON "availability_windows" ("country_code", "starts_at", "ends_at");
CREATE INDEX "idx_windows_title_country"
ON "availability_windows" ("title_id", "country_code");

CREATE TABLE IF NOT EXISTS "watch_progress" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Whose progress this is. A profile, never an account - this is the column that keeps a housemate out of your Continue Watching row.
	"profile_id" BIGINT NOT NULL,
	-- Title being watched, denormalised from the episode so Continue Watching can be built without joining up through seasons.
	"title_id" BIGINT NOT NULL,
	-- Episode being watched. Null for a film.
	"episode_id" BIGINT,
	-- Resume point. Written every few seconds by the player, so this is the hottest update path in the system.
	"position_seconds" INTEGER NOT NULL DEFAULT 0,
	-- Runtime snapshot at the time of playback, so the progress bar is drawable without a second read.
	"duration_seconds" INTEGER NOT NULL,
	-- Set once the credits marker is passed. Separate from position because a viewer who stops 30 seconds early has still finished it.
	"completed" BOOLEAN NOT NULL DEFAULT false,
	-- Last playback activity. The sort key for Continue Watching.
	"watched_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "watch_progress" IS 'One row per profile per playable, updated in place. It is deliberately current state rather than a log: the resume point is the only thing the player needs, and a log of every heartbeat would be orders of magnitude larger.';
COMMENT ON COLUMN "watch_progress"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "watch_progress"."profile_id" IS 'Whose progress this is. A profile, never an account - this is the column that keeps a housemate out of your Continue Watching row.';
COMMENT ON COLUMN "watch_progress"."title_id" IS 'Title being watched, denormalised from the episode so Continue Watching can be built without joining up through seasons.';
COMMENT ON COLUMN "watch_progress"."episode_id" IS 'Episode being watched. Null for a film.';
COMMENT ON COLUMN "watch_progress"."position_seconds" IS 'Resume point. Written every few seconds by the player, so this is the hottest update path in the system.';
COMMENT ON COLUMN "watch_progress"."duration_seconds" IS 'Runtime snapshot at the time of playback, so the progress bar is drawable without a second read.';
COMMENT ON COLUMN "watch_progress"."completed" IS 'Set once the credits marker is passed. Separate from position because a viewer who stops 30 seconds early has still finished it.';
COMMENT ON COLUMN "watch_progress"."watched_at" IS 'Last playback activity. The sort key for Continue Watching.';

CREATE UNIQUE INDEX "uq_watch_progress_profile_playable"
ON "watch_progress" ("profile_id", "title_id", "episode_id");
CREATE INDEX "idx_watch_progress_profile_recent"
ON "watch_progress" ("profile_id", "watched_at");

CREATE TABLE IF NOT EXISTS "list_items" (
	-- Profile that saved the title.
	"profile_id" BIGINT,
	-- Saved title. Composite key, so saving twice is a no-op rather than a duplicate row.
	"title_id" BIGINT,
	-- When it was saved. My List is sorted by this by default, which is why no explicit position column exists.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("profile_id", "title_id")
);

COMMENT ON TABLE "list_items" IS 'My List. It holds titles, never episodes - nobody saves episode 4 of a series - which is another thing the single titles table makes simple.';
COMMENT ON COLUMN "list_items"."profile_id" IS 'Profile that saved the title.';
COMMENT ON COLUMN "list_items"."title_id" IS 'Saved title. Composite key, so saving twice is a no-op rather than a duplicate row.';
COMMENT ON COLUMN "list_items"."added_at" IS 'When it was saved. My List is sorted by this by default, which is why no explicit position column exists.';

CREATE INDEX "idx_list_items_profile_added"
ON "list_items" ("profile_id", "added_at");

CREATE TABLE IF NOT EXISTS "ratings" (
	-- Profile that rated.
	"profile_id" BIGINT,
	-- Title rated. One rating per profile per title, enforced by the key.
	"title_id" BIGINT,
	-- thumbs_down | thumbs_up | love. A three-point scale, not five stars: the signal feeds recommendations, and people rate far more often when the choice is coarse.
	"rating" VARCHAR(16) NOT NULL,
	-- When the rating was last set. Overwritten on change - unlike watch data, nobody needs the history of your opinion.
	"rated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("profile_id", "title_id")
);

COMMENT ON TABLE "ratings" IS 'Explicit taste signal per profile. Ratings are sparse and voluntary; watch_progress is the implicit signal that actually drives the home page.';
COMMENT ON COLUMN "ratings"."profile_id" IS 'Profile that rated.';
COMMENT ON COLUMN "ratings"."title_id" IS 'Title rated. One rating per profile per title, enforced by the key.';
COMMENT ON COLUMN "ratings"."rating" IS 'thumbs_down | thumbs_up | love. A three-point scale, not five stars: the signal feeds recommendations, and people rate far more often when the choice is coarse.';
COMMENT ON COLUMN "ratings"."rated_at" IS 'When the rating was last set. Overwritten on change - unlike watch data, nobody needs the history of your opinion.';

CREATE TABLE IF NOT EXISTS "devices" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account the device is registered to.
	"account_id" BIGINT NOT NULL,
	-- Profile last active on the device, so the app can reopen on it. Null before anyone picks a profile.
	"profile_id" BIGINT,
	-- tv | phone | tablet | browser | console.
	"device_type" VARCHAR(24) NOT NULL,
	-- Stable client identifier. Unique, so a reinstall that reuses it is recognised as the same device rather than eating another stream slot.
	"device_token" VARCHAR(128) NOT NULL UNIQUE,
	-- Last seen address, used for the household check and territory enforcement.
	"last_ip" INET,
	-- Last activity. Concurrent-stream limits are enforced against recent rows here rather than against a counter that can leak on a crash.
	"last_seen_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "devices" IS 'Registered playback devices. Counting live sessions here is what enforces accounts.max_streams; a counter column would drift every time a client died mid-stream.';
COMMENT ON COLUMN "devices"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "devices"."account_id" IS 'Account the device is registered to.';
COMMENT ON COLUMN "devices"."profile_id" IS 'Profile last active on the device, so the app can reopen on it. Null before anyone picks a profile.';
COMMENT ON COLUMN "devices"."device_type" IS 'tv | phone | tablet | browser | console.';
COMMENT ON COLUMN "devices"."device_token" IS 'Stable client identifier. Unique, so a reinstall that reuses it is recognised as the same device rather than eating another stream slot.';
COMMENT ON COLUMN "devices"."last_ip" IS 'Last seen address, used for the household check and territory enforcement.';
COMMENT ON COLUMN "devices"."last_seen_at" IS 'Last activity. Concurrent-stream limits are enforced against recent rows here rather than against a counter that can leak on a crash.';

CREATE INDEX "idx_devices_account_seen"
ON "devices" ("account_id", "last_seen_at");

